CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS import_batches(id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('subscribers','web_events','app_users')), filename text NOT NULL, checksum text NOT NULL, row_count integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,checksum));
CREATE TABLE IF NOT EXISTS people(id text PRIMARY KEY, email text UNIQUE, newsletter boolean NOT NULL DEFAULT false, signup_date date, status text NOT NULL DEFAULT 'app-only', source text NOT NULL DEFAULT 'Unknown', last_open_date date, duplicate_count integer NOT NULL DEFAULT 0, conflict boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS raw_records(id text PRIMARY KEY, batch_id text NOT NULL REFERENCES import_batches(id), row_number integer NOT NULL, person_id text REFERENCES people(id), kind text NOT NULL, original jsonb NOT NULL, flags text[] NOT NULL DEFAULT '{}', UNIQUE(batch_id,row_number));
CREATE INDEX IF NOT EXISTS raw_person_idx ON raw_records(person_id);
ALTER TABLE people ADD COLUMN IF NOT EXISTS test boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS app_users(user_id text PRIMARY KEY, person_id text NOT NULL REFERENCES people(id), email text, created_at timestamptz, original jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS app_person_idx ON app_users(person_id);
CREATE TABLE IF NOT EXISTS visitors(visitor_id text PRIMARY KEY, person_id text REFERENCES people(id), ambiguous boolean NOT NULL DEFAULT false, claims jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS web_events(id text PRIMARY KEY, batch_id text NOT NULL REFERENCES import_batches(id), person_id text REFERENCES people(id), visitor_id text NOT NULL REFERENCES visitors(visitor_id), page text NOT NULL, timestamp timestamptz NOT NULL, utm_source text, original jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS web_person_time_idx ON web_events(person_id,timestamp);
CREATE INDEX IF NOT EXISTS web_visitor_idx ON web_events(visitor_id);
CREATE TABLE IF NOT EXISTS app_events(event_id text PRIMARY KEY, event text NOT NULL CHECK(event IN ('app_open','read_story','link_click','login')), user_id text REFERENCES app_users(user_id), resolved_user_id text REFERENCES app_users(user_id), device_id text NOT NULL, timestamp timestamptz NOT NULL, ingested_at timestamptz NOT NULL DEFAULT now(), properties jsonb NOT NULL, payload_hash text NOT NULL, test boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS app_device_time_idx ON app_events(device_id,timestamp);
CREATE INDEX IF NOT EXISTS app_resolved_idx ON app_events(resolved_user_id,timestamp);
CREATE TABLE IF NOT EXISTS segments(id text PRIMARY KEY, name text NOT NULL, definition jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY, action text NOT NULL, actor text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY, window_at timestamptz NOT NULL DEFAULT now(), hits integer NOT NULL DEFAULT 1);
INSERT INTO schema_migrations(version) VALUES (1) ON CONFLICT DO NOTHING;
